import fs from 'node:fs';
import {rows} from './equation-inventory.mjs';
import {hasInteractiveModel} from '../dist/models.js';
const diagrams=new Map(),reviewed=new Set();
let course;
const review=id=>{course=id;reviewed.add(id);};
const add=(id,d)=>{const key=course+'/'+id;if(!rows.some(r=>r.key===key))throw Error('Unknown lesson '+key);if(diagrams.has(key))throw Error('Duplicate '+key);diagrams.set(key,d);};
const sample=(fn,a,b,n=32)=>Array.from({length:n+1},(_,i)=>{const x=a+(b-a)*i/n;return [x,fn(x)];});
const S=(label,points,extra={})=>({label,points,...extra});
const P=(id,title,caption,xlabel,xrange,ylabel,yrange,series)=>add(id,{kind:'plot',title,caption,x:{label:xlabel,range:xrange},y:{label:ylabel,range:yrange},series});
const B=(id,title,caption,unit,values)=>add(id,{kind:'bars',title,caption,unit,values});
const R=(id,title,caption,scales)=>add(id,{kind:'scales',title,caption,scales:scales.map(([label,values])=>({label,values}))});
const C=(id,title,caption,total,shaded,columns)=>add(id,{kind:'cells',title,caption,total,shaded,columns});
// Each entry uses the lesson's own example. Curves are model calculations, not measurements.
review('foundations');
R('units','One shelf, two units','The aligned marks describe the same length. The shelf does not grow when we change units.',[['Metres',[0,0.6,1.2,1.8]],['Centimetres',[0,60,120,180]]]);
P('relationships','The belt travels steadily','Each second adds 0.4 metres. The last point is the example’s 2 metres after 5 seconds.','Time (s)',[0,5],'Distance (m)',[0,2],[S('Belt distance',[[0,0],[5,2]])]);
P('vectors','Across, up, then straight to the finish','The dashed route is 6 m east and 8 m north. The straight line joins the same start and finish; its length is 10 m. Both axes use the same scale.','East (m)',[0,8],'North (m)',[0,8],[S('Straight start-to-finish line',[[0,0],[6,8]]),S('Driven route',[[0,0],[6,0],[6,8]])]);
P('graphs','Read two places on the graph','Position rises by 6 m while time passes by 3 s. The straight line shows the steady motion used to connect these readings.','Time (s)',[0,4],'Position (m)',[0,8],[S('Position',[[1,2],[4,8]])]);
P('accumulation','The areas count signed change','The area above zero adds 6 m. The area below zero subtracts 2 m. Together they give +4 m.','Time (s)',[0,5],'Velocity (m/s)',[-2,2],[S('Rightward leg',[[0,2],[3,2]],{fill:true}),S('Leftward leg',[[3,-1],[5,-1]],{fill:true})]);
P('uncertainty','An estimate with an uncertainty','The centre is 40 cm. The stated uncertainty reaches 1 cm each way; it does not give a probability by itself.','Length (cm)',[38,42],'Marker height (no units)',[0,1],[S('Stated interval',[[39,0.5],[41,0.5]]),S('Estimate',[[40,0.2],[40,0.8]])]);
review('math');
P('trigonometry','Two parts of one arrow','The slanted arrow ends 1 m across and about 1.732 m up. Its length is 2 m. Both axes use the same metre scale.','Horizontal part (m)',[0,2],'Vertical part (m)',[0,2],[S('Arrow',[[0,0],[1,Math.sqrt(3)]]),S('Horizontal and vertical parts',[[0,0],[1,0],[1,Math.sqrt(3)]])]);
P('signed-components','Left and up are signed directions','The endpoint is −3 m across and +4 m up. The length from zero to this endpoint is 5 m. Both axes use the same scale.','Horizontal part (m)',[-4,4],'Vertical part (m)',[0,4],[S('Arrow',[[0,0],[-3,4]]),S('Parts',[[0,0],[-3,0],[-3,4]])]);
P('derivatives','A curve and its local slope','At input 3, the curve has value 9. The dashed line has slope 6 and closely follows the curve near that point.','Input x (no units)',[2,4],'Output (no units)',[3,16],[S('Square rule',sample(x=>x*x,2,4)),S('Slope line at x = 3',[[2,3],[4,15]])]);
P('integrals','Area gives the position change','The shaded triangle has area 9 m. Its height is velocity, so the area gives displacement, not velocity.','Time (s)',[0,3],'Velocity (m/s)',[0,6],[S('Steadily rising velocity',[[0,0],[3,6]],{fill:true})]);
P('antiderivatives','The starting value shifts the line','At zero seconds the velocity is already 2 m/s. Each second adds another 3 m/s in this model.','Time (s)',[0,2],'Velocity (m/s)',[0,8],[S('Velocity',[[0,2],[2,8]])]);
P('definite-integrals','Add the area between two inputs','Only the interval from 1 to 3 is shaded. The area under the line is 8 in this unit-free example.','Input x (no units)',[0,4],'Output 2x (no units)',[0,8],[S('Included part of the line',[[1,2],[3,6]],{fill:true})]);
P('linearization','A straight estimate near a curve','Near input 3 the straight estimate is close. At 3.1 it gives 9.6, while the curve gives 9.61.','Input x (no units)',[2.8,3.2],'Output (no units)',[7.7,10.3],[S('Exact square',sample(x=>x*x,2.8,3.2)),S('Straight estimate',[[2.8,7.8],[3.2,10.2]])]);
P('complex','Two parts locate one number','The endpoint is 2 across and 3 up. Its distance from zero is √13. The lines show number parts, not a path through physical space.','Real part (no units)',[0,4],'Imaginary part (no units)',[0,4],[S('Complex number',[[0,0],[2,3]]),S('Its two parts',[[0,0],[2,0],[2,3]])]);
P('projections','Keep only the horizontal part','The full vector ends at (3,4). Its projection along the horizontal direction ends at (3,0).','Horizontal part (no units)',[0,4],'Vertical part (no units)',[0,4],[S('Full vector',[[0,0],[3,4]]),S('Projection',[[0,0],[3,0]])]);
P('odes','A smooth amount falls over time','This model starts at 100 units and reaches about 36.8 after 5 s. The curve describes an amount or average.','Time (s)',[0,5],'Amount (units)',[0,100],[S('Model amount',sample(t=>100*Math.exp(-0.2*t),0,5))]);
P('exponential-decay','Each half-life halves what remains','The amount goes from 100 to 50, then to 25. The second drop is smaller because less remains.','Time (half-lives)',[0,2],'Amount (units)',[0,100],[S('Model amount',sample(t=>100*2**(-t),0,2))]);
P('oscillator-ode','The position repeats','The object starts at +3 cm, moves through zero, and comes back. One cycle takes about 3.14 s.','Time (s)',[0,Math.PI],'Position (cm)',[-3,3],[S('Position',sample(t=>3*Math.cos(2*t),0,Math.PI,48))]);
P('fourier','Adding two waves changes the shape','The solid line is the sum of the two wave ingredients. All three repeat within this same one-second interval.','Time (s)',[0,1],'Signal (no units)',[-1.4,1.4],[S('Sum',sample(t=>Math.sin(2*Math.PI*t)+.3*Math.sin(6*Math.PI*t),0,1,64)),S('1 Hz ingredient',sample(t=>Math.sin(2*Math.PI*t),0,1,64)),S('3 Hz ingredient',sample(t=>.3*Math.sin(6*Math.PI*t),0,1,64))]);
P('probability','A shaded area is a chance','The density is 0.5 per metre. The shaded interval is 0.5 m wide, so its area is 0.25: a 25% chance.','Position (m)',[0,2],'Probability density (1/m)',[0,1],[S('Whole density',[[0,.5],[2,.5]]),S('Chosen interval',[[.5,.5],[1,.5]],{fill:true})]);
C('prep-fractions','Three of four equal parts','Each square is one equal part of the sheet. Three of the four parts are shaded.',4,3,4);
C('prep-decimals','Twenty-five of a hundred','Each small square is one hundredth. The 25 shaded squares make 0.25 of the whole.',100,25,10);
R('prep-negative-numbers','Two steps to the right','Start at −3 °C. Moving right by 2 degrees ends at −1 °C.',[['Temperature (°C)',[-3,-2,-1]],['Steps from the start',[0,1,2]]]);
C('prep-powers','Three rows of three','Three equal rows with three counters in each row make nine counters.',9,9,3);
P('prep-proportions','Twice the tickets, twice the cost','The same straight rule passes through 3 tickets for 9 coins and 6 tickets for 18 coins. Tickets come in whole numbers.','Tickets (count)',[0,6],'Cost (coins)',[0,18],[S('Ticket choices',Array.from({length:7},(_,n)=>[n,3*n]),{join:false})]);
P('prep-exponentials','Each round doubles the amount','The four dots show the starting amount and the next three rounds: 5, 10, 20 and 40 counters.','Round (count)',[0,3],'Counters (count)',[0,40],[S('Amount after each round',[[0,5],[1,10],[2,20],[3,40]],{join:false})]);
R('prep-change','Read the change on one scale','The start is 2 m and the finish is 7 m. There are five one-metre gaps between them.',[['Position (m)',[2,3,4,5,6,7]]]);
review('mechanics');
