P('conservative-force','Energy rises away from the centre','At 2 m the energy curve slopes upward at 12 J/m. The force points the other way: −12 N.','Position (m)',[-2,2],'Potential energy (J)',[0,12],[S('Potential energy',sample(x=>3*x*x,-2,2))]);
