// Keep geometric diagrams faithful: both physical directions use the same scale.
for(const key of ['advanced-mechanics/constraint','plasma/gyroradius','foundations/vectors','math/trigonometry','math/signed-components','math/complex','math/projections','optics/reflection-normal','optics/snell-index'])diagrams.get(key).equalAspect=true;
// A horizontal uncertainty interval needs no invented vertical quantity.
diagrams.set('foundations/uncertainty',{kind:'scales',title:'An estimate with an uncertainty',caption:'The middle mark is the 40 cm estimate. The outer marks are one stated uncertainty away, at 39 and 41 cm. This interval alone does not say how likely a value is.',scales:[{label:'Length (cm)',values:[39,40,41]}]});
for(const [key,d]of diagrams){
 if(d.kind==='plot'){
  for(const axis of [d.x,d.y])if(!(axis.range[1]>axis.range[0]))throw Error(key+': invalid axis');
  for(const s of d.series)for(const p of s.points)for(let i=0;i<2;i++)if(!Number.isFinite(p[i])||p[i]<[d.x,d.y][i].range[0]-1e-8||p[i]>[d.x,d.y][i].range[1]+1e-8)throw Error(key+': point outside axes '+p);
  for(const s of d.series)if(s.fill&&(d.y.range[0]>0||d.y.range[1]<0))throw Error(key+': shaded area needs zero');
 }
}

for(const cid of new Set(rows.map(r=>r.course))){
 const lessons=Object.fromEntries([...diagrams].filter(([key])=>key.startsWith(cid+'/')).map(([key,d])=>[key.slice(cid.length+1),d]));
 fs.mkdirSync(new URL('../dist/content/visuals/',import.meta.url),{recursive:true});
 fs.writeFileSync(new URL('../dist/content/visuals/'+cid+'.json',import.meta.url),JSON.stringify({lessons},null,2)+'\n');
}
const audit=rows.map(r=>({key:r.key,title:r.title,reviewed:reviewed.has(r.course),decision:diagrams.has(r.key)?'added':hasInteractiveModel(r.lesson.visual)?'existing-interactive':['concept',''].includes(r.lesson.visual?.type??'')?'text-sufficient':'existing-summary',reason:diagrams.has(r.key)?diagrams.get(r.key).caption:hasInteractiveModel(r.lesson.visual)?'An interactive model already lets the learner explore this relationship.':r.focus.equation?'The worked example is a short calculation or rule; its labeled equation and steps carry the main idea.':'The distinction is explained directly in the short example; a quantitative graph would need extra assumptions.'}));
fs.writeFileSync(new URL('../docs/lesson-visual-audit.json',import.meta.url),JSON.stringify({reviewedCourses:[...reviewed],total:rows.length,added:diagrams.size,lessons:audit},null,2)+'\n');
